  /* ===== ABS (30) ===== */
  Q("abs", "L'ABS d'un PL travaille principalement avec", ["La pression d'air de freinage", "Le débit d'AdBlue", "La pression des pneus uniquement", "Le couple du pont"], 0, "Le modulateur ABS joue sur l'air des freins, pas sur le carburant ni l'AdBlue.");
